testsCode:
#include <stdio.h>

/* teste do desafio o-abridor — counter_protocol (03-tdd 3.9.3).
   Canal retorno: nenhuma captura de stdout. O que se confere e o valor
   devolvido e o efeito no disco.
   Cada cenario SEMEIA o caderno antes de chamar (um fopen "w" com uma
   linha conhecida): assim o fopen de leitura nunca devolve NULL, e o
   diretorio de execucao — que e o MESMO na prova da solucao e na prova do
   starter — nasce em estado conhecido, sem herdar a rodada anterior.
   Abrir em "w" ZERA o arquivo no instante em que abre: e por isso que a
   linha semeada desaparecer e a prova de que o fopen do aluno rodou. */

/* prototipo da funcao do aluno (o teste declara o que exercita) */
int oAbridor(void);

SM_TEST(o_abridor_devolve_um) {
    FILE *semente = fopen("diario.txt", "w");
    fprintf(semente, "linha semeada pelo teste\n");
    fclose(semente);

    checa_int("o abridor devolve 1", oAbridor(), 1,
              "abrir diario.txt em modo w da certo: o fopen nao devolve NULL");
}

SM_TEST(o_caderno_foi_aberto_em_w) {
    FILE *semente = fopen("diario.txt", "w");
    fprintf(semente, "linha semeada pelo teste\n");
    fclose(semente);

    oAbridor();

    FILE *f = fopen("diario.txt", "r");
    char linha[80] = "(caderno vazio)";
    fgets(linha, 80, f);
    checa_str("o caderno ficou vazio no disco", linha, "(caderno vazio)",
              "o modo w zera o caderno ao abrir: a linha semeada saiu, e o arquivo continua no disco");
    fclose(f);
}

solutionCode:
#include <stdio.h>

int oAbridor(void) {
    FILE *f = fopen("diario.txt", "w");
    if (f == NULL) {
        return 0;
    }
    fclose(f);
    return 1;
}
